// Generated by scripts/build.cjs. Edit src/, then rebuild.
// Preview appearance picker — 跟随系统 + texlate 槽位色板 floating menu.
// Built into preview.js, loaded through the host's trusted local head entry.
// Only writes the appearance preference; CSS resolves colors and print policy.
// localStorage is scoped to the current webview origin.
(function () {
    "use strict";
    // Import sets can be re-fetched without a full reload — never double-mount.
    if (window.__xnoteThemeToggle) return;
    window.__xnoteThemeToggle = { mount: boot };

    var STORAGE_KEY = "xnote-theme";
    var ORDER=["system","editor","paper","sepia","snow","dark","onedark","black"];
var LABELS={"system":"跟随系统","editor":"跟随编辑器","paper":"暖纸","sepia":"羊皮纸","snow":"雪白","dark":"暖黑","onedark":"One Dark","black":"纯黑"};
var DOTS={"system":["#f5f1e8","#17140f"],"editor":["#f5f1e8","#17140f"],"paper":["#f5f1e8","#211b12"],"sepia":["#f4ecd8","#5b4636"],"snow":["#eceff4","#3b4252"],"dark":["#17140f","#e6ddcb"],"onedark":["#282c34","#abb2bf"],"black":["#000000","#ffffff"]};
    // Pre-slot localStorage values still select the same resolved palettes.
    var LEGACY = { light: "paper", dark: "dark" };

    function readState() {
        try {
            var v = localStorage.getItem(STORAGE_KEY);
            if (LEGACY[v]) return LEGACY[v];
            return ORDER.indexOf(v) >= 0 ? v : "system";
        } catch (e) {
            return "system";
        }
    }

    function writeState(v) {
        try {
            localStorage.setItem(STORAGE_KEY, v);
        } catch (e) {
            // Storage disabled — the in-session override still applies.
        }
    }

    function dot(name) {
        var d = DOTS[name];
        return (
            '<span class="xnote-dot" style="background:linear-gradient(135deg,' +
            d[0] +
            " 50%," +
            d[1] +
            ' 50%)"></span>'
        );
    }

    var button = null;
    var menu = null;

    function render(state) {
        document.body.setAttribute("data-xnote-theme", state);
        if (button) {
            button.innerHTML = dot(state);
            var label = "外观：" + LABELS[state];
            button.title = label;
            button.setAttribute("aria-label", label);
        }
        if (menu) {
            var items = menu.querySelectorAll("[data-xnote-slot]");
            for (var i = 0; i < items.length; i++) {
                items[i].setAttribute(
                    "aria-checked",
                    items[i].getAttribute("data-xnote-slot") === state
                        ? "true"
                        : "false",
                );
            }
        }
    }

    function closeMenu() {
        if (!menu) return;
        menu.remove();
        menu = null;
        button.setAttribute("aria-expanded", "false");
        document.removeEventListener("click", onDocClick, true);
        document.removeEventListener("keydown", onKeyDown, true);
    }

    function onDocClick(e) {
        if (menu && !menu.contains(e.target) && !button.contains(e.target))
            closeMenu();
    }

    function onKeyDown(e) {
        if (e.key === "Escape") {
            e.stopPropagation();
            closeMenu();
            button.focus();
        }
    }

    function select(name) {
        writeState(name);
        render(name);
        closeMenu();
    }

    function openMenu() {
        menu = document.createElement("div");
        menu.id = "xnote-theme-menu";
        // MPE counter-zooms `.fixed` chrome when the preview is zoomed — the
        // class is redundant styling-wise (id rule already sets position:fixed)
        // but keeps the menu pinned to the corner instead of drifting.
        menu.className = "fixed";
        menu.setAttribute("role", "menu");
        menu.setAttribute("aria-label", "外观");
        var current = readState();
        for (var i = 0; i < ORDER.length; i++) {
            var name = ORDER[i];
            var item = document.createElement("button");
            item.type = "button";
            item.className = "xnote-theme-item";
            item.setAttribute("role", "menuitemradio");
            item.setAttribute("data-xnote-slot", name);
            item.setAttribute(
                "aria-checked",
                name === current ? "true" : "false",
            );
            item.innerHTML =
                dot(name) +
                '<span class="xnote-theme-label">' +
                LABELS[name] +
                "</span>" +
                '<span class="xnote-theme-check" aria-hidden="true">✓</span>';
            item.addEventListener("click", onItemClick);
            menu.appendChild(item);
        }
        document.body.appendChild(menu);
        button.setAttribute("aria-expanded", "true");
        // capture 阶段挂：menu 内 item 的 click 先命中 onItemClick 选槽关菜单，
        // 外部点击则由 onDocClick 关掉。
        document.addEventListener("click", onDocClick, true);
        document.addEventListener("keydown", onKeyDown, true);
    }

    function onItemClick(e) {
        e.stopPropagation();
        select(e.currentTarget.getAttribute("data-xnote-slot"));
    }

    function onButtonClick(e) {
        e.stopPropagation();
        if (menu) closeMenu();
        else openMenu();
    }

    function boot() {
        if (!document.body || (button && button.isConnected)) return;
        if (button) {
            closeMenu();
            document.body.appendChild(button);
            render(readState());
            return;
        }
        button = document.createElement("button");
        button.id = "xnote-theme-toggle";
        button.className = "fixed";
        button.type = "button";
        button.setAttribute("aria-haspopup", "menu");
        button.setAttribute("aria-expanded", "false");
        button.addEventListener("click", onButtonClick);
        document.body.appendChild(button);
        render(readState());
    }

    // The trusted head entry can execute before body is available.
    if (document.body) boot();
    else document.addEventListener("DOMContentLoaded", boot);
})();

(function () {
    "use strict";
    if (window.__xnotePreviewBootstrap) return;
    window.__xnotePreviewBootstrap = true;
    var base = document.currentScript && document.currentScript.src;
    var requested = new Set();
    var frame = 0;
    function load(name, target, label) {
        if (!base || requested.has(name)) return;
        requested.add(name);
        var script = document.createElement("script");
        script.src = new URL(name, base).href;
        script.addEventListener(
            "error",
            function () {
                var error = document.createElement("p");
                error.className = "xnote-diagram-status";
                error.setAttribute("role", "alert");
                error.textContent = label + "加载失败，请重新打开预览以重试。";
                target.after(error);
            },
            { once: true },
        );
        document.head.appendChild(script);
    }
    function scan() {
        // The host's first React commit may replace body children after the
        // trusted head script ran. Reattach chrome without mounting twice.
        window.__xnoteThemeToggle.mount();
        var diagram = document.querySelector(
            ".markdown-preview .mermaid > svg",
        );
        if (diagram)
            load("diagram-actions.js", diagram.parentElement, "图表工具");
        var source = document.querySelector(
            ".markdown-preview pre.language-pseudocode > code, .markdown-preview pre > code.language-pseudocode",
        );
        if (source)
            load(
                "pseudocode-runtime.js",
                source.parentElement,
                "伪代码回退工具",
            );
    }
    var observer = new MutationObserver(function (records) {
        if (
            !frame &&
            records.some(function (r) {
                return r.addedNodes.length > 0;
            })
        ) {
            frame = requestAnimationFrame(function () {
                frame = 0;
                scan();
            });
        }
    });
    function boot() {
        observer.observe(document.body, { childList: true, subtree: true });
        scan();
    }
    if (document.body) boot();
    else document.addEventListener("DOMContentLoaded", boot, { once: true });
})();
